        if (d[i][i] != 0) { printf("-1\n"); return 0; }
        for (int j = 0; j < n; j++) {
            if (d[i][j] != d[j][i]) { printf("-1\n"); return 0; }
            if (i != j && d[i][j] <= 0) { printf("-1\n"); return 0; }
        }
    }

    // Check triangle inequality
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            for (int k = 0; k < n; k++)
                if (d[i][j] > d[i][k] + d[k][j]) { printf("-1\n"); return 0; }

    // Find minimum spanning set of edges
    long long total = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i+1; j < n; j++) {
            // Check if edge (i,j) is necessary
            int necessary = 1;
            for (int k = 0; k < n; k++) {
                if (k == i || k == j) continue;
                if (d[i][k] + d[k][j] == d[i][j]) {
                    necessary = 0;
                    break;
                }
