    // Check consistency and prepare a copy for Floyd-Warshall
    long long dist[N][N];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            dist[i][j] = d[i][j];
        }
    }

    // Floyd-Warshall
    for (int k = 0; k < N; k++) {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
    }

    // Check if input matrix matches shortest paths
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (dist[i][j] != d[i][j]) {
                printf("-1\n");
                return 0;
            }
        }
    }

    // Find minimal total road length
    long long total = 0;
    bool needed[N][N];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            needed[i][j] = true;
        }
    }

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            bool redundant = false;
            for (int k = 0; k < N; k++) {
                if (k != i && k != j && d[i][j] == d[i][k] + d[k][j]) {
                    redundant = true;
                    break;
                }
            }
            if (!redundant) {
                total += d[i][j];
            }
        }
    }

    printf("%lld\n", total);
    return 0;
}

